     1	package com.pousadamarealta.messaging;
     2	
     3	import java.util.List;
     4	
     5	public class EmailValidationRule implements MessageRule {
     6	    @Override
     7	    public List<OutboundMessage> apply(OutboundMessage message) {
     8	        if (!isValidEmail(message.getTo())) {
     9	            message.setBlocked(true);
    10	        }
    11	        return List.of(message);
    12	    }
    13	
    14	    private boolean isValidEmail(String email) {
    15	        if (email == null || email.isEmpty()) {
    16	            return false;
    17	        }
    18	
    19	        long atCount = email.chars().filter(ch -> ch == '@').count();
    20	        if (atCount != 1) {
    21	            return false;
    22	        }
    23	
    24	        int atIndex = email.indexOf('@');
    25	        if (atIndex == 0 || atIndex == email.length() - 1) {
    26	            return false;
    27	        }
    28	
    29	        String domain = email.substring(atIndex + 1);
    30	        if (!domain.contains(".")) {
    31	            return false;
    32	        }
    33	
    34	        return true;
    35	    }
    36	}
