    14	        List<OutboundMessage> messages = List.of(message);
    15	
    16	        for (MessageRule rule : rules) {
    17	            List<OutboundMessage> newMessages = new ArrayList<>();
    18	            for (OutboundMessage msg : messages) {
    19	                newMessages.addAll(rule.apply(msg));
    20	            }
    21	            messages = newMessages;
    22	        }
    23	
    24	        return messages;
    25	    }
    26	}
