     9	import java.util.ArrayList;
    10	import java.util.List;
    11	
    12	public class MessageService {
    13	    private final MessageRepository messageRepository;
    14	    private final MessagePipeline pipeline;
    15	
    16	    public MessageService(MessageRepository messageRepository, boolean isTestMode) {
    17	        this.messageRepository = messageRepository;
    18	        this.pipeline = createPipeline(isTestMode);
    19	    }
    20	
    21	    private MessagePipeline createPipeline(boolean isTestMode) {
    22	        List<MessageRule> rules = new ArrayList<>();
    23	        rules.add(new EmailValidationRule());
    24	
    25	        if (isTestMode) {
    26	            rules.add(new TestModeRule());
    27	        } else {
    28	            rules.add(new ArchiveCopyRule());
    29	        }
    30	
    31	        return new MessagePipeline(rules);
    32	    }
    33	
    34	    public void sendMessage(MessageChannel channel, String to, String subject, String body) {
    35	        OutboundMessage outbound = new OutboundMessage(channel, to, subject, body);
    36	        List<OutboundMessage> processedMessages = pipeline.process(outbound);
    37	
    38	        for (OutboundMessage msg : processedMessages) {
    39	            MessageStatus status = msg.isBlocked() ? MessageStatus.BLOCKED : MessageStatus.SENT;
    40	            Message message = new Message(
    41	                messageRepository.nextId(),
    42	                msg.getChannel(),
    43	                msg.getTo(),
    44	                msg.getSubject(),
    45	                msg.getBody(),
    46	                status
    47	            );
    48	            messageRepository.save(message);
    49	        }
    50	    }
    51	
    52	    public List<Message> getAllMessages() {
    53	        return messageRepository.findAll();
    54	    }
    55	}
