  3	import com.pousadamarealta.domain.*;
  4	import com.pousadamarealta.repository.ReservationRepository;
  5	import com.pousadamarealta.repository.RoomRepository;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.time.format.DateTimeFormatter;
 10	import java.time.temporal.ChronoUnit;
 11	import java.util.List;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepository;
 15	    private final RoomRepository roomRepository;
 16	    private final PricingService pricingService;
 17	    private final MessageService messageService;
 18	
 19	    public ReservationService(ReservationRepository reservationRepository,
 20	                             RoomRepository roomRepository,
 21	                             PricingService pricingService,
 22	                             MessageService messageService) {
 23	        this.reservationRepository = reservationRepository;
 24	        this.roomRepository = roomRepository;
 25	        this.pricingService = pricingService;
 26	        this.messageService = messageService;
 27	    }
 28	
 29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
 30	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 31	        Room room = roomRepository.findByNumber(roomNumber)
 32	                .orElseThrow(() -> new RoomNotFoundException());
 33	
 34	        if (guests < 1) {
 35	            throw new InvalidRequestException("Number of guests must be at least 1");
 36	        }
 37	
 38	        if (guests > room.getCapacity()) {
 39	            throw new CapacityExceededException();
 40	        }
 41	
 42	        if (!checkOut.isAfter(checkIn)) {
 43	            throw new InvalidRequestException("Check-out must be after check-in");
 44	        }
 45	
 46	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 47	        if (!conflicts.isEmpty()) {
 48	            throw new RoomUnavailableException();
 49	        }
 50	
 51	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 52	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
 53	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
 54	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
 55	
 56	        Long id = reservationRepository.nextId();
 57	        Reservation reservation = new Reservation(
 58	                id, roomNumber, guestName, guestEmail, guestCpf,
 59	                checkIn, checkOut, guests, ratePlan,
 60	                nights, subtotal, discount, total
 61	        );
 62	
 63	        return reservationRepository.save(reservation);
 64	    }
 65	
 66	    public Reservation getReservation(Long id) {
 67	        return reservationRepository.findById(id)
 68	                .orElseThrow(() -> new ReservationNotFoundException());
 69	    }
 70	
 71	    public Reservation confirmReservation(Long id) {
 72	        Reservation reservation = getReservation(id);
 73	
 74	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 75	            throw new OperationNotAllowedException();
 76	        }
 77	
 78	        reservation.setStatus(ReservationStatus.CONFIRMED);
 79	        reservation.setAmountPaid(reservation.getTotal());
 80	        reservationRepository.save(reservation);
 81	
 82	        sendConfirmationEmail(reservation);
 83	
 84	        return reservation;
 85	    }
 86	
 87	    public Reservation cancelReservation(Long id) {
 88	        Reservation reservation = getReservation(id);
 89	
 90	        if (reservation.getStatus() != ReservationStatus.PENDING &&
 91	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
 92	            throw new OperationNotAllowedException();
 93	        }
 94	
 95	        BigDecimal refund = BigDecimal.ZERO;
 96	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
 97	            refund = reservation.getAmountPaid();
 98	        }
 99	
100	        reservation.setStatus(ReservationStatus.CANCELLED);
101	        reservation.setRefund(refund);
102	        reservationRepository.save(reservation);
103	
104	        return reservation;
105	    }
106	
107	    public Reservation checkIn(Long id) {
108	        Reservation reservation = getReservation(id);
109	
110	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
111	            throw new OperationNotAllowedException();
112	        }
113	
114	        reservation.setStatus(ReservationStatus.CHECKED_IN);
115	        reservationRepository.save(reservation);
116	
117	        return reservation;
118	    }
119	
120	    public String checkOut(Long id) {
121	        Reservation reservation = getReservation(id);
122	
123	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
124	            throw new OperationNotAllowedException();
125	        }
126	
127	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
128	        reservationRepository.save(reservation);
129	
130	        return generateReceipt(reservation);
131	    }
132	
133	    public String getDocument(Long id) {
134	        Reservation reservation = getReservation(id);
135	
136	        if (reservation.getStatus() == ReservationStatus.PENDING ||
137	            reservation.getStatus() == ReservationStatus.CANCELLED) {
138	            throw new OperationNotAllowedException();
139	        }
140	
141	        return generateReceipt(reservation);
142	    }
143	
144	    private void sendConfirmationEmail(Reservation reservation) {
145	        String receipt = generateReceipt(reservation);
146	        String subject = "Reserva confirmada - Pousada Maré Alta";
147	        String body = String.format(
148	                "Olá, %s!\n\n" +
149	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
150	                "%s\n\n" +
151	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
152	                "Até breve!",
153	                reservation.getGuestName(),
154	                receipt
155	        );
156	
157	        messageService.sendMessage(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
158	    }
159	
160	    private String generateReceipt(Reservation reservation) {
161	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
162	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
163	
164	        StringBuilder receipt = new StringBuilder();
165	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
166	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
167	        receipt.append(String.format("Quarto: %s (%s)\n", reservation.getRoomNumber(), room.getType()));
168	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
169	                reservation.getCheckIn().format(dateFormatter),
170	                reservation.getCheckOut().format(dateFormatter),
171	                reservation.getNights(),
172	                reservation.getNights() == 1 ? "diária" : "diárias"));
173	        receipt.append(String.format("Diárias: %s\n", formatCurrency(reservation.getSubtotal())));
174	
175	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
176	            receipt.append(String.format("Desconto: %s\n", formatCurrency(reservation.getDiscount())));
177	        }
178	
179	        receipt.append(String.format("Total: %s", formatCurrency(reservation.getTotal())));
180	
181	        return receipt.toString();
182	    }
183	
184	    private String formatCurrency(BigDecimal amount) {
185	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
186	    }
187	
188	    private String formatCpf(String cpf) {
189	        if (cpf.length() == 11) {
190	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
191	        }
192	        return cpf;
193	    }
194	
195	    public static class RoomNotFoundException extends RuntimeException {}
196	    public static class ReservationNotFoundException extends RuntimeException {}
197	    public static class RoomUnavailableException extends RuntimeException {}
198	    public static class OperationNotAllowedException extends RuntimeException {}
199	    public static class CapacityExceededException extends RuntimeException {}
200	    public static class InvalidRequestException extends RuntimeException {
201	        public InvalidRequestException(String message) {
202	            super(message);
203	        }
204	    }
205	}
