208	import com.pousadamarealta.domain.RatePlan;
209	import com.pousadamarealta.domain.Room;
210	import com.pousadamarealta.util.DateUtils;
211	
212	import java.math.BigDecimal;
213	import java.math.RoundingMode;
214	import java.time.LocalDate;
215	
216	public class PricingService {
217	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
218	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
219	
220	    public BigDecimal calculateNightPrice(Room room, LocalDate night) {
221	        BigDecimal basePrice = room.getNightlyRate();
222	        if (DateUtils.isHighSeason(night)) {
223	            basePrice = basePrice.multiply(HIGH_SEASON_MULTIPLIER);
224	        }
225	        return basePrice.setScale(2, RoundingMode.HALF_EVEN);
226	    }
227	
228	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
229	        BigDecimal subtotal = BigDecimal.ZERO;
230	        LocalDate current = checkIn;
231	
232	        while (current.isBefore(checkOut)) {
233	            BigDecimal nightPrice = calculateNightPrice(room, current);
234	            subtotal = subtotal.add(nightPrice);
235	            current = current.plusDays(1);
236	        }
237	
238	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
239	    }
240	
241	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
242	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
243	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
244	        }
245	        return BigDecimal.ZERO;
246	    }
247	
248	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
249	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
250	    }
251	}
