263	import java.util.List;
264	
265	public class ReportService {
266	    private final ReservationRepository reservationRepository;
267	    private final RoomRepository roomRepository;
268	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
269	
270	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
271	        this.reservationRepository = reservationRepository;
272	        this.roomRepository = roomRepository;
273	    }
274	
275	    public String generateOccupancyReport(LocalDate date) {
276	        List<Reservation> reservations = reservationRepository.findByNight(date);
277	        int totalRooms = roomRepository.findAll().size();
278	
279	        StringBuilder csv = new StringBuilder();
280	        csv.append("room,type,reservation,check_in,check_out\n");
281	
282	        for (Reservation reservation : reservations) {
283	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
284	            csv.append(String.format("%s,%s,%d,%s,%s\n",
285	                    reservation.getRoomNumber(),
286	                    room.getType(),
287	                    reservation.getId(),
288	                    reservation.getCheckIn().format(DATE_FORMATTER),
289	                    reservation.getCheckOut().format(DATE_FORMATTER)));
290	        }
291	
292	        csv.append(String.format("total,%d/%d", reservations.size(), totalRooms));
293	
294	        return csv.toString();
295	    }
296	
297	    public String generateRevenueReport(YearMonth month) {
298	        List<Reservation> reservations = reservationRepository.findByMonth(month);
299	
300	        StringBuilder csv = new StringBuilder();
301	        csv.append("reservation,room,check_in,check_out,status,amount\n");
302	
303	        BigDecimal total = BigDecimal.ZERO;
304	
305	        for (Reservation reservation : reservations) {
306	            BigDecimal amount = reservation.getAmountPaid();
307	            if (reservation.getRefund() != null) {
308	                amount = amount.subtract(reservation.getRefund());
309	            }
310	
311	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
312	                    reservation.getId(),
313	                    reservation.getRoomNumber(),
314	                    reservation.getCheckIn().format(DATE_FORMATTER),
315	                    reservation.getCheckOut().format(DATE_FORMATTER),
316	                    reservation.getStatus(),
317	                    formatAmount(amount)));
318	
319	            total = total.add(amount);
320	        }
321	
322	        csv.append(String.format("total,%s", formatAmount(total)));
323	
324	        return csv.toString();
325	    }
326	
327	    private String formatAmount(BigDecimal amount) {
328	        return amount.setScale(2).toString().replace(",", ".");
329	    }
330	}

