 29	
 30	    public Long nextId() {
 31	        return idGenerator.getAndIncrement();
 32	    }
 33	
 34	    public List<Reservation> findByRoomAndDateRange(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
 35	        return reservations.values().stream()
 36	                .filter(r -> r.getRoomNumber().equals(roomNumber))
 37	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 38	                .filter(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut))
 39	                .collect(Collectors.toList());
 40	    }
