 42	    public List<Reservation> findByNight(LocalDate night) {
 43	        return reservations.values().stream()
 44	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 45	                .filter(r -> r.getStatus() != ReservationStatus.PENDING)
 46	                .filter(r -> !r.getCheckIn().isAfter(night) && r.getCheckOut().isAfter(night))
 47	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
 48	                .collect(Collectors.toList());
 49	    }
