 51	    public List<Reservation> findByMonth(YearMonth month) {
 52	        LocalDate start = month.atDay(1);
 53	        LocalDate end = month.atEndOfMonth();
 54	
 55	        return reservations.values().stream()
 56	                .filter(r -> !r.getCheckIn().isBefore(start) && !r.getCheckIn().isAfter(end))
 57	                .filter(r -> r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO).compareTo(BigDecimal.ZERO) > 0)
 58	                .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId))
 59	                .collect(Collectors.toList());
