323	    private String getRequiredField(JsonNode json, String field) throws MissingFieldException {
324	        if (!json.has(field) || json.get(field).isNull()) {
325	            throw new MissingFieldException("Missing required field: " + field);
326	        }
327	        return json.get(field).asText();
328	    }
