330	    private int getRequiredIntField(JsonNode json, String field) throws MissingFieldException {
331	        if (!json.has(field) || json.get(field).isNull()) {
332	            throw new MissingFieldException("Missing required field: " + field);
333	        }
334	        return json.get(field).asInt();
335	    }
