414	
415	        if (month == Month.DECEMBER && day >= 15) {
416	            return true;
417	        }
418	
419	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
420	            return true;
421	        }
422	
423	        if (month == Month.JULY) {
424	            return true;
425	        }
426	
427	        return false;
428	    }
